INSERT INTO `#__content` (`id`, `asset_id`, `title`, `alias`, `introtext`, `fulltext`, `state`, `catid`, `created`, `created_by`, `created_by_alias`, `modified`, `modified_by`, `checked_out`, `checked_out_time`, `publish_up`, `publish_down`, `images`, `urls`, `attribs`, `version`, `ordering`, `metakey`, `metadesc`, `access`, `hits`, `metadata`, `featured`, `language`, `xreference`, `note`) VALUES
(1, 62, 'A city of light for Northwind Architects', 'a-city-of-light-for-northwind-architects', '<p>A new identity and portfolio site for an architecture practice whose buildings change colour with the hour.</p>', '<h2>The brief</h2><p>Northwind had outgrown a template website that showed its buildings as small, grey thumbnails. They wanted a home that felt like walking through their work.</p><h2>What we did</h2><p>We built a modular identity around the warm glass of their towers, and a website where every project opens full-screen, with drawings, materials and a timeline of the build.</p><blockquote><p>Fast, thoughtful and calm under pressure. We would hire them again tomorrow.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>3×</strong> longer visits</li><li><strong>41%</strong> more enquiries</li><li><strong>8</strong> weeks from kickoff to launch</li></ul><dl class="facts"><dt>Client</dt><dd>Northwind Architects</dd><dt>Services</dt><dd>Brand identity, Web design</dd></dl>', 1, 8, '2026-10-04 03:30:00', 384, 'Mara Ellis', '2026-10-04 03:30:00', 0, 0, '0000-00-00 00:00:00', '2026-10-04 03:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/orange-towers.webp","image_intro_alt":"Orange glass towers seen from below","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/orange-towers.webp","image_fulltext_alt":"Orange glass towers seen from below","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 8, '', '', 1, 1493, '{"author":"","rights":"","xreference":""}', 1, '*', '', ''),
(2, 64, 'Seeing the grid with Halden Energy', 'seeing-the-grid-with-halden-energy', '<p>A live dashboard that turns two hundred wind turbines into one clear picture for the people who run them.</p>', '<h2>The brief</h2><p>Halden''s operators watched six different tools to keep an offshore wind farm running. Alarms were missed, and new staff took months to learn the systems.</p><h2>What we did</h2><p>We spent two weeks in the control room, then designed and built one dashboard: a map of the farm, the turbines that need attention first, and the weather that will matter next.</p><blockquote><p>They listened first and designed second. It shows in every screen.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>62%</strong> faster response to alarms</li><li><strong>1</strong> screen instead of six</li><li><strong>99.98%</strong> uptime since launch</li></ul><dl class="facts"><dt>Client</dt><dd>Halden Energy</dd><dt>Services</dt><dd>Product design, Engineering</dd></dl>', 1, 8, '2026-09-10 05:30:00', 384, 'Ines Kovač', '2026-09-10 05:30:00', 0, 0, '0000-00-00 00:00:00', '2026-09-10 05:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/news\\/energy\\/energy-17.webp","image_intro_alt":"Offshore wind turbines at sea","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/news\\/energy\\/energy-17.webp","image_fulltext_alt":"Offshore wind turbines at sea","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 7, '', '', 1, 3842, '{"author":"","rights":"","xreference":""}', 1, '*', '', ''),
(3, 66, 'The Aperture museum after dark', 'the-aperture-museum-after-dark', '<p>An exhibition website for a museum of light, built to feel as playful as the rooms it describes.</p>', '<h2>The brief</h2><p>The museum''s night programme sold out in person but barely existed online. They needed a site that could sell tickets and carry the atmosphere of the galleries.</p><h2>What we did</h2><p>Every exhibition gets a page of moving light made with plain CSS and a few lines of script, so it loads fast on a phone in a queue outside. Tickets take three taps.</p><blockquote><p>They listened first and designed second. It shows in every screen.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>2.1 s</strong> largest contentful paint on 4G</li><li><strong>+54%</strong> online ticket sales</li><li><strong>0</strong> third-party scripts</li></ul><dl class="facts"><dt>Client</dt><dd>Aperture Museum of Light</dd><dt>Services</dt><dd>Web design, Motion</dd></dl>', 1, 8, '2026-08-18 08:30:00', 384, 'Mara Ellis', '2026-08-18 08:30:00', 0, 0, '0000-00-00 00:00:00', '2026-08-18 08:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/light-painting.webp","image_intro_alt":"Red and blue streaks of light over water at night","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/light-painting.webp","image_fulltext_alt":"Red and blue streaks of light over water at night","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 6, '', '', 1, 2244, '{"author":"","rights":"","xreference":""}', 1, '*', '', ''),
(4, 68, 'Vela Towers, from launch to living room', 'vela-towers-from-launch-to-living-room', '<p>A launch campaign for two residential towers, from the hoarding on the street to the welcome pack on the kitchen table.</p>', '<h2>The brief</h2><p>Vela had a remarkable building and a crowded market. The first homes had to sell before the second tower topped out.</p><h2>What we did</h2><p>We named the towers, designed the identity around their twist, and ran one campaign across print, street and a small, quick website with floor plans that work on any screen.</p><blockquote><p>The new work feels like us, only clearer. Our customers noticed within a week.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>78%</strong> of homes reserved before completion</li><li><strong>12</strong> weeks of campaign</li><li><strong>5</strong> design awards</li></ul><dl class="facts"><dt>Client</dt><dd>Vela Residences</dd><dt>Services</dt><dd>Brand identity, Campaign</dd></dl>', 1, 8, '2026-08-03 04:30:00', 384, 'Mara Ellis', '2026-08-03 04:30:00', 0, 0, '0000-00-00 00:00:00', '2026-08-03 04:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/twisting-tower.webp","image_intro_alt":"A twisting tower lit at night","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/twisting-tower.webp","image_fulltext_alt":"A twisting tower lit at night","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 5, '', '', 1, 2520, '{"author":"","rights":"","xreference":""}', 0, '*', '', ''),
(5, 70, 'Outdoor gear for Aurora Outfitters', 'outdoor-gear-for-aurora-outfitters', '<p>A new shop for an outdoor brand whose customers buy on the move, often on a weak signal at the edge of the map.</p>', '<h2>The brief</h2><p>Aurora''s old shop was slow, and half of their customers left before the product page had loaded. Returns were high because sizes were hard to judge.</p><h2>What we did</h2><p>We rebuilt the shop around speed and clarity: small pages, images sized for each screen, a size guide drawn from real returns, and a checkout that survives a dropped connection.</p><blockquote><p>They listened first and designed second. It shows in every screen.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>−38%</strong> returns</li><li><strong>+27%</strong> mobile conversion</li><li><strong>1.4 s</strong> average page load</li></ul><dl class="facts"><dt>Client</dt><dd>Aurora Outfitters</dd><dt>Services</dt><dd>E-commerce, Web design</dd></dl>', 1, 8, '2026-07-12 08:30:00', 384, 'Ines Kovač', '2026-07-12 08:30:00', 0, 0, '0000-00-00 00:00:00', '2026-07-12 08:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/polar-lights.webp","image_intro_alt":"Green and red polar lights over a forest","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/polar-lights.webp","image_fulltext_alt":"Green and red polar lights over a forest","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 4, '', '', 1, 3146, '{"author":"","rights":"","xreference":""}', 1, '*', '', ''),
(6, 72, 'An open data platform for the city', 'an-open-data-platform-for-the-city', '<p>A developer platform that publishes a city''s open data with documentation people actually enjoy reading.</p>', '<h2>The brief</h2><p>The city released hundreds of data sets a year, but few developers used them: formats changed without notice and the documentation was a set of PDFs.</p><h2>What we did</h2><p>We designed a versioned API, a catalogue with search and previews, and documentation written alongside the code, so every example is tested before it is published.</p><blockquote><p>They turned a complicated problem into something our whole team understands.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>340</strong> data sets published</li><li><strong>5×</strong> more API keys issued</li><li><strong>100%</strong> of examples tested</li></ul><dl class="facts"><dt>Client</dt><dd>Open City Data</dd><dt>Services</dt><dd>Engineering, Product design</dd></dl>', 1, 8, '2026-06-21 07:30:00', 384, 'Theo Brandt', '2026-06-21 07:30:00', 0, 0, '0000-00-00 00:00:00', '2026-06-21 07:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/code-screens.webp","image_intro_alt":"Two screens with code on a dark desk","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/code-screens.webp","image_fulltext_alt":"Two screens with code on a dark desk","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 3, '', '', 1, 310, '{"author":"","rights":"","xreference":""}', 0, '*', '', ''),
(7, 74, 'A furniture brand with holes in all the right places', 'a-furniture-brand-with-holes-in-all-the-right-places', '<p>An identity for a young furniture maker, drawn from the perforated steel at the heart of its first collection.</p>', '<h2>The brief</h2><p>Perfora had one beautiful collection, a tiny budget and no name customers could remember.</p><h2>What we did</h2><p>We named the company after its material and built the whole identity from a grid of round holes: the logo, a typeface of dots, flat-pack boxes and a one-page shop.</p><blockquote><p>Fast, thoughtful and calm under pressure. We would hire them again tomorrow.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>1</strong> grid behind everything</li><li><strong>3</strong> retailers signed in the first month</li><li><strong>0</strong> plastic in the packaging</li></ul><dl class="facts"><dt>Client</dt><dd>Perfora</dd><dt>Services</dt><dd>Brand identity, Packaging</dd></dl>', 1, 8, '2026-05-28 07:30:00', 384, 'Mara Ellis', '2026-05-28 07:30:00', 0, 0, '0000-00-00 00:00:00', '2026-05-28 07:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/perforated-facade.webp","image_intro_alt":"A white perforated building against a teal sky","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/perforated-facade.webp","image_fulltext_alt":"A white perforated building against a teal sky","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 2, '', '', 1, 1174, '{"author":"","rights":"","xreference":""}', 0, '*', '', ''),
(8, 76, 'Spiral Records, around and around', 'spiral-records-around-and-around', '<p>A refreshed identity and a listening-first website for an independent record label celebrating twenty years.</p>', '<h2>The brief</h2><p>After twenty years and four hundred releases, Spiral''s catalogue was scattered across platforms and its own site had not changed in a decade.</p><h2>What we did</h2><p>We gave the logo a quarter turn and built a site where the whole catalogue plays in the browser, release by release, with liner notes written by the artists.</p><blockquote><p>They listened first and designed second. It shows in every screen.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>400</strong> releases online</li><li><strong>+65%</strong> direct sales</li><li><strong>20</strong> years celebrated</li></ul><dl class="facts"><dt>Client</dt><dd>Spiral Records</dd><dt>Services</dt><dd>Brand identity, Web design, Motion</dd></dl>', 1, 8, '2026-05-07 09:30:00', 384, 'Mara Ellis', '2026-05-07 09:30:00', 0, 0, '0000-00-00 00:00:00', '2026-05-07 09:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/studio\\/spiral-stairs.webp","image_intro_alt":"A white and yellow spiral staircase from above","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/spiral-stairs.webp","image_fulltext_alt":"A white and yellow spiral staircase from above","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, 1, '', '', 1, 463, '{"author":"","rights":"","xreference":""}', 0, '*', '', ''),
(9, 78, 'Quiet infrastructure for Cirrus Hosting', 'quiet-infrastructure-for-cirrus-hosting', '<p>A control panel for a hosting company that wanted its customers to forget their servers were there.</p>', '<h2>The brief</h2><p>Cirrus had fast, reliable servers and a control panel that generated more support tickets than any outage.</p><h2>What we did</h2><p>We mapped the twenty tasks customers do most, designed one clear path for each, and rebuilt the panel as a set of small, accessible components the Cirrus team now owns.</p><blockquote><p>They listened first and designed second. It shows in every screen.</p></blockquote><h2>Results</h2><ul class="figures"><li><strong>−45%</strong> support tickets</li><li><strong>20</strong> tasks redesigned</li><li><strong>AA</strong> WCAG level met</li></ul><dl class="facts"><dt>Client</dt><dd>Cirrus Hosting</dd><dt>Services</dt><dd>Product design, Engineering</dd></dl>', 1, 8, '2026-04-20 09:30:00', 384, 'Sam Okoye', '2026-04-20 09:30:00', 0, 0, '0000-00-00 00:00:00', '2026-04-20 09:30:00', '0000-00-00 00:00:00', '{"image_intro":"images\\/sampledata\\/news\\/technology\\/technology-06.webp","image_intro_alt":"Rows of servers lit blue in a data centre","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/news\\/technology\\/technology-06.webp","image_fulltext_alt":"Rows of servers lit blue in a data centre","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options