(95, 121, 'Search', '', '', 0, 'search', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_search', 1, 0, '{"label":"Search","width":"","text":"Search the studio\\u2026","button":1,"button_pos":"right","imagebutton":0,"button_text":"Search","opensearch":0,"opensearch_title":"","set_itemid":0,"layout":"_:default","moduleclass_sfx":"","cache":1,"cache_time":900,"cachemode":"itemid","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(96, 122, 'Hero', '', '<div class="hero"><img class="heroImage" src="images/sampledata/studio/light-curves.webp" srcset="images/sampledata/studio/light-curves-960.webp 960w, images/sampledata/studio/light-curves.webp 1920w" sizes="100vw" width="1920" height="1080" alt="" fetchpriority="high" /><div class="container heroBody"><p class="eyebrow">Design &amp; technology studio</p><h1 class="displayTitle">We design and build <span class="highlight">bold digital things.</span></h1><p class="lead">Brands, websites and products for people who care about the details, made by a small team of designers and engineers.</p><div class="actions">{loadposition hero-actions,none}</div></div></div>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 0, '{"prepare_content":1,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"section-full","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(97, 123, 'Clients', '', '<ul class="namesStrip"><li class="namesLabel">Trusted by teams at</li><li>Northwind</li><li>Halden Energy</li><li>Aperture</li><li>Vela</li><li>Aurora</li><li>Open City</li><li>Perfora</li><li>Spiral Records</li></ul>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 0, '{"prepare_content":0,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"names","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(98, 124, 'What we do', '', '<ul class="services"><li class="service"><span class="serviceNumber">01</span><h3>Brand identity</h3><p>Names, logos, type and colour systems with a point of view, and the guidelines to keep them sharp.</p></li><li class="service"><span class="serviceNumber">02</span><h3>Websites</h3><p>Fast, accessible sites on content management systems your team will actually enjoy using.</p></li><li class="service"><span class="serviceNumber">03</span><h3>Products</h3><p>Research, interface design and prototypes for apps and tools, from first sketch to release.</p></li><li class="service"><span class="serviceNumber">04</span><h3>Engineering</h3><p>Front-end and back-end development, design systems and the infrastructure to run them.</p></li></ul>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 1, '{"prepare_content":0,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(99, 125, 'Selected work', '', '', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_articles_category', 1, 1, '{"mode":"normal","show_on_article_page":1,"count":5,"show_front":"show","category_filtering_type":1,"catid":[8],"show_child_category_articles":0,"levels":1,"author_filtering_type":1,"author_alias_filtering_type":1,"excluded_articles":"","date_filtering":"off","date_field":"a.created","start_date_range":"","end_date_range":"","relative_date":30,"article_ordering":"publish_up","article_ordering_direction":"DESC","article_grouping":"none","date_grouping_field":"created","month_year_format":"F Y","article_grouping_direction":"ksort","link_titles":1,"show_date":1,"show_date_field":"publish_up","show_date_format":"Y-m-d H:i:s","show_category":0,"show_hits":0,"show_author":1,"show_tags":0,"show_introtext":1,"introtext_limit":200,"show_readmore":0,"show_readmore_title":1,"readmore_limit":15,"layout":"rookwood:work","moduleclass_sfx":"tone-alt divider-wave","owncache":1,"cache_time":900,"module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(100, 126, 'Inside the studio', '', '<div class="band"><img class="bandImage" src="images/sampledata/studio/violet-desk.webp" srcset="images/sampledata/studio/violet-desk-960.webp 960w, images/sampledata/studio/violet-desk.webp 1920w" sizes="100vw" width="1920" height="1080" alt="" loading="lazy" decoding="async" /><div class="container bandBody"><h2>Small team. Big ideas.</h2><div><p>Twenty-four designers, engineers and producers in a converted foundry. Senior people on every project, from the first workshop to the launch and long after it.</p><div class="actions">{loadposition studio-link,none}</div></div></div></div>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 0, '{"prepare_content":1,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"section-full","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(101, 127, 'In numbers', '', '<ul class="stats"><li><strong>14</strong><span>years in practice</span></li><li><strong>120+</strong><span>projects launched</span></li><li><strong>24</strong><span>designers and engineers</span></li><li><strong>9</strong><span>design awards</span></li></ul>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 0, '{"prepare_content":0,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"tone-accent divider-wave","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(102, 128, 'What clients say', '', '<figure class="bigQuote"><blockquote><p>Rookwood understood what we were trying to say before we did, then built something faster and braver than we had asked for.</p></blockquote><figcaption><span class="avatar" style="--hue:320">EV</span><span><strong>Elena Vasquez</strong>, Director, Aperture Museum</span></figcaption></figure>', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 0, '{"prepare_content":0,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(103, 129, 'From the journal', '', '', 0, 'frontpage', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_articles_category', 1, 1, '{"mode":"normal","show_on_article_page":1,"count":3,"show_front":"show","category_filtering_type":1,"catid":[9],"show_child_category_articles":0,"levels":1,"author_filtering_type":1,"author_alias_filtering_type":1,"excluded_articles":"","date_filtering":"off","date_field":"a.created","start_date_range":"","end_date_range":"","relative_date":30,"article_ordering":"publish_up","article_ordering_direction":"DESC","article_grouping":"none","date_grouping_field":"created","month_year_format":"F Y","article_grouping_direction":"ksort","link_titles":1,"show_date":1,"show_date_field":"publish_up","show_date_format":"Y-m-d H:i:s","show_category":0,"show_hits":0,"show_author":1,"show_tags":0,"show_introtext":1,"introtext_limit":200,"show_readmore":0,"show_readmore_title":1,"readmore_limit":15,"layout":"rookwood:journal","moduleclass_sfx":"tone-alt divider-wave","owncache":1,"cache_time":900,"module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
(104, 130, 'Explore', '', '', 0, 'footer', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_menu', 1, 1, '{"menutype":"mainmenu","startLevel":1,"endLevel":1,"showAllChildren":1,"tag_id":"","class_sfx":"","window_open":"","layout":"_:default","moduleclass_sfx":"","cache":1,"cache_time":900,"cachemode":"itemid","module_tag":"div","header_tag":"h3","header_class":"","style":"0"}', 0, '*'),
(105, 131, 'Visit', '', '<p>Unit 4, The Old Foundry</p><p>27 Kiln Yard, Rookwood</p><p>+44 20 7946 0958</p>', 0, 'footer', 0, '0000-00-00 00:00:00', '0000-00-00 00:00:00', '0000-00-00 00:00:00', 1, 'mod_custom', 1, 1, '{"prepare_content":0,"backgroundimage":"","layout":"_:default","moduleclass_sfx":"","cache":1,"cache_time":900,"cachemode":"static","module_tag":"div","header_tag":"h3","header_class":""}', 0, '*'),
