(1, 'com_content.article', 'A city of light for Northwind Architects', 'a-city-of-light-for-northwind-architects', '<p>A new identity and portfolio site for an architecture practice whose buildings change colour with the hour.</p>', 1, '0000-00-00 00:00:00', 0, 1, '{"article_layout":"","show_title":"","link_titles":"","show_intro":"","show_category":"","link_category":"","show_parent_category":"","link_parent_category":"","show_author":"","link_author":"","show_create_date":"","show_modify_date":"","show_publish_date":"","show_item_navigation":"","show_icons":"","show_print_icon":"","show_email_icon":"","show_vote":"","show_hits":"","show_noauth":"","alternative_readmore":"","article_page_title":"","show_publishing_options":"","show_article_options":"","show_urls_images_backend":"","show_urls_images_frontend":""}', 1, '{"author":"","rights":"","xreference":""}', 384, '', '2026-10-04 03:30:00', 0, '2026-10-04 03:30:00', '*', '2026-10-04 03:30:00', '0000-00-00 00:00:00', 1, 63, '{"image_intro":"images\\/sampledata\\/studio\\/orange-towers.webp","image_intro_alt":"Orange glass towers seen from below","image_intro_caption":"","image_fulltext":"images\\/sampledata\\/studio\\/orange-towers.webp","image_fulltext_alt":"Orange glass towers seen from below","image_fulltext_caption":""}', '{"urla":false,"urlatext":"","targeta":"","urlb":false,"urlbtext":"","targetb":"","urlc":false,"urlctext":"","targetc":""}', 0, 1, 0, '', '', 8, '', 1),
