--
-- IMPORTANT - THIS FILE MUST BE SAVED WITH UTF-8 ENCODING ONLY. BEWARE IF EDITING!
--
-- The Studio sample data, for the Rookwood template. Generated by docs/sample-data/build/build.sh
-- from a fresh install and the command line (articles, categories, tags, menus and modules); its images are in
-- images/sampledata/news. The installer moves its dates forward, keeping the time between them.
--

SET FOREIGN_KEY_CHECKS=0;
SET SQL_MODE="NO_AUTO_VALUE_ON_ZERO";
SET time_zone = "+00:00";

TRUNCATE `#__assets`;
TRUNCATE `#__categories`;
TRUNCATE `#__content`;
TRUNCATE `#__content_frontpage`;
TRUNCATE `#__contentitem_tag_map`;
TRUNCATE `#__menu`;
TRUNCATE `#__menu_types`;
TRUNCATE `#__modules`;
TRUNCATE `#__modules_menu`;
TRUNCATE `#__tags`;
TRUNCATE `#__ucm_base`;
TRUNCATE `#__ucm_content`;

