-- The Rookwood template's settings for the Studio site
--

UPDATE `#__template_styles` SET `params` = '{"siteName": "Rookwood Studio", "defaultTheme": "dark", "footerHeadline": "Have a project in mind? Let''s talk.", "footerEmail": "hello@example.com", "footerText": "A fictional studio, made for demonstrating Joomla 3.x UTD.", "social_x": "#", "social_linkedin": "#", "social_instagram": "#", "social_github": "#", "social_dribbble": "#", "social_rss": ""}' WHERE `template` = 'rookwood' AND `client_id` = 0;
